package coupons.repository;

import coupons.*;
import java.sql.*;
import java.time.LocalDate;
import java.util.*;

/** PostgreSQL clipped-coupon store with one-time redemption enforcement. */
public final class PostgresClippedCouponRepository implements ClippedCouponRepository {
    private final PostgresConnectionFactory connections;
    public PostgresClippedCouponRepository(PostgresConnectionFactory connections){this.connections=Objects.requireNonNull(connections);}
    @Override public void save(ClippedCoupon x,String actor){Objects.requireNonNull(x);PostgresRepositorySupport.requireActor(actor,"Recorded by");if(x.revision()!=1)throw new IllegalArgumentException("New coupon revision must be one.");PostgresRepositorySupport.transaction(connections,c->{try(PreparedStatement p=c.prepareStatement("INSERT INTO clipped_coupon_current(coupon_id,provider,external_id,status,revision,payload) VALUES (?,?,?,?,?,?)")){p.setObject(1,x.couponId());p.setString(2,x.provider());p.setString(3,x.externalId());p.setString(4,x.status().name());p.setLong(5,1);p.setBytes(6,PostgresRepositorySupport.serialize(x));p.executeUpdate();}catch(SQLException e){if("23505".equals(e.getSQLState()))throw new IllegalArgumentException("Coupon already exists.",e);throw e;}history(c,x,actor,"initial coupon");return null;});}
    @Override public Optional<ClippedCoupon> findById(UUID id){return find("coupon_id=?",Objects.requireNonNull(id));}
    @Override public List<ClippedCoupon> findByProvider(String provider){PostgresRepositorySupport.requireActor(provider,"Provider");return PostgresRepositorySupport.transaction(connections,c->{List<ClippedCoupon> out=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT payload FROM clipped_coupon_current WHERE provider=? ORDER BY coupon_id")){p.setString(1,provider);try(ResultSet r=p.executeQuery()){while(r.next())out.add(PostgresRepositorySupport.deserialize(r.getBytes(1),ClippedCoupon.class));}}return List.copyOf(out);});}
    private Optional<ClippedCoupon> find(String where,Object value){return PostgresRepositorySupport.transaction(connections,c->{try(PreparedStatement p=c.prepareStatement("SELECT payload FROM clipped_coupon_current WHERE "+where)){p.setObject(1,value);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(PostgresRepositorySupport.deserialize(r.getBytes(1),ClippedCoupon.class)):Optional.empty();}}});}
    @Override public ClippedCoupon update(ClippedCoupon x,long expected,String actor,String reason){Objects.requireNonNull(x);PostgresRepositorySupport.requireActor(actor,"Changed by");PostgresRepositorySupport.requireActor(reason,"Reason");if(expected<1||x.revision()!=expected+1)throw new IllegalArgumentException("Invalid coupon revision.");return PostgresRepositorySupport.transaction(connections,c->{long stored;try(PreparedStatement p=c.prepareStatement("SELECT revision FROM clipped_coupon_current WHERE coupon_id=? FOR UPDATE")){p.setObject(1,x.couponId());try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Coupon does not exist.");stored=r.getLong(1);}}if(stored!=expected)throw new ConcurrentModificationException("Coupon revision changed.");write(c,x);history(c,x,actor,reason);return x;});}
    @Override public ClippedCoupon redeem(UUID id,UUID transactionId,LocalDate date,long expected,String actor){Objects.requireNonNull(id);Objects.requireNonNull(transactionId);Objects.requireNonNull(date);PostgresRepositorySupport.requireActor(actor,"Redeemed by");return PostgresRepositorySupport.transaction(connections,c->{ClippedCoupon old;try(PreparedStatement p=c.prepareStatement("SELECT payload FROM clipped_coupon_current WHERE coupon_id=? FOR UPDATE")){p.setObject(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Coupon does not exist.");old=PostgresRepositorySupport.deserialize(r.getBytes(1),ClippedCoupon.class);}}if(old.revision()!=expected)throw new ConcurrentModificationException("Coupon revision changed.");if(old.status()==CouponStatus.APPLIED||old.redeemedTransactionId()!=null)throw new IllegalStateException("Coupon has already been redeemed.");if(old.status()!=CouponStatus.CLIPPED)throw new IllegalStateException("Only clipped coupons can be redeemed.");if(old.coupon().getExpirationDate()!=null&&date.isAfter(old.coupon().getExpirationDate()))throw new IllegalArgumentException("Coupon expired on "+old.coupon().getExpirationDate()+".");ClippedCoupon next=new ClippedCoupon(old.couponId(),old.provider(),old.externalId(),old.coupon(),CouponStatus.APPLIED,old.clippedOn(),date,transactionId,expected+1);try{try(PreparedStatement p=c.prepareStatement("INSERT INTO clipped_coupon_redemptions(coupon_id,transaction_id,redeemed_on) VALUES (?,?,?)")){p.setObject(1,id);p.setObject(2,transactionId);p.setObject(3,date);p.executeUpdate();}}catch(SQLException e){if("23505".equals(e.getSQLState()))throw new IllegalStateException("Coupon or transaction has already been used.",e);throw e;}write(c,next);history(c,next,actor,"redeemed");return next;});}
    private static void write(Connection c,ClippedCoupon x)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE clipped_coupon_current SET provider=?,external_id=?,status=?,revision=?,payload=? WHERE coupon_id=?")){p.setString(1,x.provider());p.setString(2,x.externalId());p.setString(3,x.status().name());p.setLong(4,x.revision());p.setBytes(5,PostgresRepositorySupport.serialize(x));p.setObject(6,x.couponId());p.executeUpdate();}}
    private static void history(Connection c,ClippedCoupon x,String actor,String reason)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO clipped_coupon_history(coupon_id,revision,changed_by,reason,payload) VALUES (?,?,?,?,?)")){p.setObject(1,x.couponId());p.setLong(2,x.revision());p.setString(3,actor);p.setString(4,reason);p.setBytes(5,PostgresRepositorySupport.serialize(x));p.executeUpdate();}}
}
